<?php
require_once __DIR__ . '/includes/bootstrap.php';
require_login();
if(is_admin()) { $rows=$conn->query('SELECT b.*,m.movie_name,u.username,u.email FROM bookings b JOIN movies m ON m.id=b.movie_id JOIN users u ON u.id=b.user_id ORDER BY b.id DESC')->fetchAll(); }
else { $s=$conn->prepare('SELECT b.*,m.movie_name FROM bookings b JOIN movies m ON m.id=b.movie_id WHERE b.user_id=:uid ORDER BY b.id DESC'); $s->execute(['uid'=>$_SESSION['id']]); $rows=$s->fetchAll(); }
page_start('Rezervimet','bookings.php');
?>
<section class="panel"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3"><h2 class="section-title mb-0"><?= is_admin()?'Menaxhimi i rezervimeve':'Rezervimet e mia' ?></h2><span class="text-secondary small"><?= count($rows) ?> gjithsej</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Filmi</th><?php if(is_admin()): ?><th>Klienti</th><th>Email</th><?php endif; ?><th>Bileta</th><th>Data</th><th>Ora</th><th>Statusi</th><?php if(is_admin()): ?><th>Veprime</th><?php endif; ?></tr></thead><tbody><?php foreach($rows as $b): ?><tr><td class="fw-semibold"><?= e($b['movie_name']) ?></td><?php if(is_admin()): ?><td><?= e($b['username']) ?></td><td><?= e($b['email']) ?></td><?php endif; ?><td><?= (int)$b['nr_tickets'] ?></td><td><?= e($b['date']) ?></td><td><?= e($b['time']) ?></td><td><span class="badge-status <?= $b['is_approved']==='true'?'status-true':($b['is_approved']==='false'?'status-false':'status-pending') ?>"><?= $b['is_approved']==='true'?'Aprovuar':($b['is_approved']==='false'?'Refuzuar':'Në pritje') ?></span></td><?php if(is_admin()): ?><td><div class="actions"><form method="post" action="booking_action.php"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><input type="hidden" name="status" value="true"><button class="btn btn-sm btn-success">Aprovo</button></form><form method="post" action="booking_action.php"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><input type="hidden" name="status" value="false"><button class="btn btn-sm btn-outline-danger">Refuzo</button></form></div></td><?php endif; ?></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="9" class="empty-state">Nuk ka ende rezervime për t'u shfaqur.</td></tr><?php endif; ?></tbody></table></div></section>
<?php page_end(); ?>
